const input = $json.body ?? $json;

const text = (value) => {
  if (value === null || value === undefined) return '';
  return String(value).trim();
};

const toBoolean = (value) => {
  if (typeof value === 'boolean') return value;
  return ['true', '1', 'yes', 'on'].includes(text(value).toLowerCase());
};

const clinic_name = text(input.clinic_name);
const clinical_intake_case_id =
  Number(input.clinical_intake_case_id);
const mobile = text(input.mobile);
const confirm_submission =
  toBoolean(input.confirm_submission);

let answers = input.answers ?? [];

if (typeof answers === 'string') {
  try {
    answers = JSON.parse(answers || '[]');
  } catch {
    answers = null;
  }
}

const errors = [];

if (!clinic_name) {
  errors.push({
    field: 'clinic_name',
    message: 'نام کلینیک الزامی است.',
  });
}

if (
  !Number.isInteger(clinical_intake_case_id) ||
  clinical_intake_case_id < 1
) {
  errors.push({
    field: 'clinical_intake_case_id',
    message: 'شناسه پرونده معتبر نیست.',
  });
}

if (!/^\+?[0-9]{8,15}$/.test(mobile)) {
  errors.push({
    field: 'mobile',
    message: 'شماره موبایل معتبر نیست.',
  });
}

if (!Array.isArray(answers)) {
  errors.push({
    field: 'answers',
    message: 'answers باید یک آرایه JSON باشد.',
  });
  answers = [];
}

if (answers.length < 1 || answers.length > 50) {
  errors.push({
    field: 'answers',
    message: 'تعداد پاسخ‌ها باید بین 1 و 50 باشد.',
  });
}

const deduplicated = new Map();

for (const item of answers) {
  if (
    !item ||
    typeof item !== 'object' ||
    Array.isArray(item)
  ) {
    errors.push({
      field: 'answers',
      message: 'هر پاسخ باید یک شیء JSON باشد.',
    });
    continue;
  }

  const questionCode = text(item.question_code);

  if (!questionCode) {
    errors.push({
      field: 'answers.question_code',
      message: 'کد سؤال برای همه پاسخ‌ها الزامی است.',
    });
    continue;
  }

  if (!Object.prototype.hasOwnProperty.call(item, 'answer')) {
    errors.push({
      field: `answers.${questionCode}`,
      message: 'مقدار answer الزامی است.',
    });
    continue;
  }

  deduplicated.set(questionCode, {
    question_code: questionCode,
    answer: item.answer,
  });
}

if (confirm_submission !== true) {
  errors.push({
    field: 'confirm_submission',
    message: 'ثبت پاسخ‌ها باید به‌صورت صریح تأیید شود.',
  });
}

const normalizedAnswers = [...deduplicated.values()];

return [{
  json: {
    clinic_name,
    clinical_intake_case_id,
    mobile,
    answers: normalizedAnswers,
    answers_json: JSON.stringify(normalizedAnswers),
    confirm_submission,
    validation_status: errors.length === 0 ? 'valid' : 'invalid',
    errors,
  },
}];

return [{
  json: {
    success: false,
    result: 'invalid_request',
    message: 'پاسخ‌های ارسالی ناقص یا نامعتبر هستند.',
    errors: $json.errors ?? [],
  },
}];
